test "corpus: chunks contract fixtures keep strict and fault targets separate under interpreter and native" {
    const gpa = std.testing.allocator;
    const io = std.testing.io;
    const root = "testdata/step44";
    const Fixture = struct {
        rel: []const u8,
        tests: u32,
        fault_percent: u32,
        held_under_faults: u32,
    };
    const fixtures = [_]Fixture{
        .{ .rel = "chunks.mo", .tests = 9, .fault_percent = 0, .held_under_faults = 0 },
        .{ .rel = "chunks-tls.mo", .tests = 2, .fault_percent = 0, .held_under_faults = 0 },
        .{
            .rel = "chunks-tls-faults.mo",
            .tests = 1,
            .fault_percent = 20,
            .held_under_faults = 1,
        },
    };
    for (fixtures) |fixture| {
        try checkContractFixture(
            gpa,
            io,
            root,
            fixture.rel,
            fixture.tests,
            fixture.fault_percent,
            fixture.held_under_faults,
        );
        try std.testing.expect(try fmtCheck(gpa, io, root, fixture.rel));
    }

    const from_environ = std.testing.environ.getAlloc(gpa, "MO_EXE") catch null;
    defer if (from_environ) |e| gpa.free(e);
    const mo_exe = try moExe(gpa, io, from_environ);
    defer gpa.free(mo_exe);
    defer Io.Dir.cwd().deleteTree(io, root ++ "/zig-out") catch {};
    var built: Built = .{};
    for (fixtures) |fixture| {
        try checkBuiltTests(gpa, io, mo_exe, root, fixture.rel, &built);
    }
    try std.testing.expectEqual(@as(u32, 0), built.wrong);
    try std.testing.expectEqual(@as(u32, fixtures.len), built.same);
    try std.testing.expectEqual(@as(u32, fixtures.len), built.succeeded);
}

test "corpus: step 42 stress runs every program under MO_STRESS in both runtimes" {
    const gpa = std.testing.allocator;
    const io = std.testing.io;
    const root = "../examples";
    const paths = collect(gpa, io, root) catch |err| switch (err) {
        error.FileNotFound => return,
        else => return err,
    };
    defer {
        for (paths) |p| gpa.free(p);
        gpa.free(paths);
    }
    const from_environ = std.testing.environ.getAlloc(gpa, "MO_EXE") catch null;
    defer if (from_environ) |e| gpa.free(e);
    const mo_exe = try moExe(gpa, io, from_environ);
    defer gpa.free(mo_exe);
    defer Io.Dir.cwd().deleteTree(io, root ++ "/zig-out") catch {};
    const stress_from_environ = std.testing.environ.getAlloc(gpa, "MO_STEP42_STRESS") catch null;
    defer if (stress_from_environ) |value| gpa.free(value);
    const stress = stress_from_environ orelse "1";

    var programs: u32 = 0;
    var interpreted_wrong: u32 = 0;
    var compiled: Built = .{};
    for (paths) |rel| {
        if (!try isRunnable(io, root, rel)) continue;
        programs += 1;
        if (!try checkProgramWith(gpa, io, mo_exe, root, rel, stress)) interpreted_wrong += 1;
        try checkBuiltProgramWith(gpa, io, mo_exe, root, rel, &compiled, stress);
    }
    try std.testing.expect(programs > 0);
    try std.testing.expectEqual(@as(u32, 0), interpreted_wrong);
    try std.testing.expectEqual(@as(u32, 0), compiled.wrong);
    try std.testing.expect(compiled.same >= programs);
}

