test "step 42: committed packed events outlive their update" {
    var arena_state = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();
    const program = try compile(arena, tx_src);
    var h: Harness = undefined;
    h.begin(arena, program, "emitted");
    h.sim.packs = true;
    const selected = for (program.tests) |t| {
        if (std.mem.eql(u8, t.name, "emitted")) break t;
    } else unreachable;
    _ = try h.machine.call(selected.function, &.{});
    defer h.sim.deinitEvents();
    try std.testing.expectEqual(@as(usize, 1), h.sim.events.items.len);
    try std.testing.expect(h.sim.events.items[0].parcel != null);
    try std.testing.expectEqualStrings("owned 0", h.sim.events.items[0].value.string);
}

reviewed_source.enqueue:
/// Puts a retained message in `to`'s mailbox, which takes its ownership.
pub fn enqueue(sim: *Sim, from: u32, to: u32, retained: ParcelValue) Error!u64 {
    const seq = sim.next_seq;
    sim.next_seq += 1;
    try sim.procs.items[to].mailbox.append(sim.gpa, .{ .retained = retained, .seq = seq });
    if (sim.turns) |t| try t.markRunnable(to);
    if (sim.schedule != null) try sim.trace.append(sim.gpa, .{ .from = from, .to = to, .message = retained.value, .took = false });
    return seq;
}

