/// A message from the runtime to process `to`, retained under `mo run`.
fn send(sim: *Sim, to: u32, name: []const u8, fields: []const Value) Error!void {
    const message = try sim.vm.variant(name, fields);
    _ = try sim.enqueue(runtime_sender, to, try sim.parcelValue(message));
}

reviewed_source.markRunnable:
/// Sim.enqueue put a message in process `id`'s mailbox.
pub fn markRunnable(t: *Turns, id: u32) Error!void {
    const s = t.scheds[t.homeOf(id)];
    if (id >= s.runnable.bit_length) try s.runnable.resize(t.gpa, @max(2 * s.runnable.bit_length, id + 64), false);
    s.runnable.set(id);
    t.stir(s);
}

